import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.DW5bL-_G.js";const u=JSON.parse('{"title":"项目介绍","description":"EW Color Picker 是事件驱动、插件化的颜色选择器。了解核心职责、13 个包的划分与数据流。","frontmatter":{"title":"项目介绍","description":"EW Color Picker 是事件驱动、插件化的颜色选择器。了解核心职责、13 个包的划分与数据流。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function n(c,e,s,l,i,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>EW Color Picker 是一个基于 <strong>事件驱动 + 插件系统</strong> 的颜色选择器。核心包只做三件事：</p><ol><li>维护当前颜色（<code>currentColor</code>）与 HSVA 状态（<code>hsvaColor</code>）；</li><li>通过实例级 <code>EventEmitter</code> 派发事件；</li><li>为插件提供 <code>root</code> 与 <code>panelContainer</code> 两个挂载点。</li></ol><p>其余所有界面元素（颜色盒、面板、色相/透明度滑块、输入框、按钮、预定义色板、颜色模式切换器）都以插件形式注册，因此可以按需组合、自由扩展。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>单一数据源</td><td>任何插件修改颜色都只调用 <code>core.setColor()</code>，再由 <code>change</code> 事件驱动其他插件同步，不存在多份颜色状态。</td></tr><tr><td>插件自治</td><td>插件自己负责渲染、事件绑定与销毁，核心不感知具体 UI。</td></tr><tr><td>可裁剪</td><td>不需要按钮就不注册 Button 插件；不需要透明度就不注册 Alpha 插件。</td></tr><tr><td>类型完备</td><td>每个包都输出 <code>.d.ts</code>，插件通过 <code>declare module</code> 扩展配置类型。</td></tr></tbody></table><h2 id="包结构" tabindex="-1">包结构 <a class="header-anchor" href="#包结构" aria-label="Permalink to &quot;包结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>@ew-color-picker/core</code></td><td>颜色状态、事件总线、插件注册与挂载点</td></tr><tr><td><code>@ew-color-picker/utils</code></td><td>DOM / 颜色 / 动画 / 事件 / 图标等基础工具</td></tr><tr><td><code>@ew-color-picker/style</code></td><td>全部样式（<code>index.css</code>、<code>input-number.css</code> 等）</td></tr><tr><td><code>@ew-color-picker/ew-color-picker</code></td><td>聚合包，注册全部内置插件，开箱即用</td></tr><tr><td><code>@ew-color-picker/box</code></td><td>触发面板的颜色盒</td></tr><tr><td><code>@ew-color-picker/panel</code></td><td>饱和度/明度面板（核心必需插件）</td></tr><tr><td><code>@ew-color-picker/hue</code></td><td>色相滑块</td></tr><tr><td><code>@ew-color-picker/alpha</code></td><td>透明度滑块</td></tr><tr><td><code>@ew-color-picker/input</code></td><td>文本输入框</td></tr><tr><td><code>@ew-color-picker/input-number</code></td><td>数字输入框组件</td></tr><tr><td><code>@ew-color-picker/button</code></td><td>清空 / 确定按钮</td></tr><tr><td><code>@ew-color-picker/predefine</code></td><td>预定义颜色色板</td></tr><tr><td><code>@ew-color-picker/color-mode</code></td><td>Hex / RGB / HSL 模式切换</td></tr><tr><td><code>@ew-color-picker/console</code></td><td>控制台版本横幅（已并入 utils）</td></tr></tbody></table><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户操作（面板拖动 / 输入框 / 色板 / 滑块）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   core.setColor(color)</span></span>
<span class="line"><span>        │  trigger(&#39;change&#39;, color)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌───────────────┬───────────────┬───────────────┐</span></span>
<span class="line"><span> │ Box 更新背景   │ Panel 更新光标 │ Input 更新值   │  …其他插件</span></span>
<span class="line"><span> └───────────────┴───────────────┴───────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><code>setColor</code> 同时会更新 <code>hsvaColor</code> 并调用 <code>options.changeColor</code> 回调。插件<strong>不应该</strong>直接修改其他插件的 DOM，而是订阅 <code>change</code> 事件自行同步。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./installation">安装</a> — 选择聚合包或按需安装子包</li><li><a href="./getting-started">快速开始</a> — 完成第一个可交互示例</li><li><a href="./concepts">核心概念</a> — 理解挂载点、插件顺序与事件</li></ul>`,13)])])}const b=t(r,[["render",n]]);export{u as __pageData,b as default};
